CREATE OR REPLACE FUNCTION create_care_group(name text, description text, is_public boolean) RETURNS SETOF care_groups LANGUAGE plpgsql SECURITY DEFINER AS $$ DECLARE v_user_id uuid; v_group_id uuid; BEGIN v_user_id := auth.uid(); INSERT INTO care_groups(name, description, is_public, created_by, created_at) VALUES (name, description, is_public, v_user_id, now()) RETURNING id INTO v_group_id; INSERT INTO care_group_members(group_id, user_id, role, joined_at) VALUES (v_group_id, v_user_id, 'owner', now()); RETURN QUERY SELECT * FROM care_groups WHERE id = v_group_id; END; $$;
